function safeImport(data){if(!data||data.type!=='hollow-frontier-3d-save'||data.version!==2||!data.world||typeof data.world!=='object')throw Error('Not a Hollow Frontier 3D backup');const w=data.world;if(!w.player||!w.inv||!Array.isArray(w.buildings))throw Error('Backup world data is incomplete');const imported=freshWorld(0,num(w.seed)||1);imported.seed=num(w.seed)>>>0;imported.name=String(w.name||'Recovered Frontier').slice(0,45);imported.day=clamp(num(w.day),1,99999);imported.clock=clamp(Number(w.clock)||.17,0,.99);imported.scene=w.scene==='expedition'?'expedition':'home';for(const k of ['x','z'])imported.player[k]=clamp(Number(w.player[k])||0,-WORLD_RADIUS,WORLD_RADIUS);for(const k of ['hp','hunger','stamina'])imported.player[k]=clamp(Number(w.player[k])||100,0,100);for(const t of TYPES)imported.inv[t]=clamp(num(w.inv[t]),0,100000);imported.scanner=!!w.scanner;imported.relay=!!w.relay;imported.ending=['contain','listen'].includes(w.ending)?w.ending:null;imported.chapter=clamp(num(w.chapter),0,6);imported.expNights=clamp(num(w.expNights),0,99999);imported.discoveries=Array.isArray(w.discoveries)?w.discoveries.slice(0,100).map(x=>String(x).slice(0,140)):['The Arrival'];imported.buildings=w.buildings.slice(0,120).filter(b=>b&&COST[b.kind]).map(b=>({kind:b.kind,x:clamp(Number(b.x)||0,-WORLD_RADIUS,WORLD_RADIUS),z:clamp(Number(b.z)||0,-WORLD_RADIUS,WORLD_RADIUS),fuel:clamp(Number(b.fuel)||0,0,9999)}));const depleted=w.depleted&&typeof w.depleted==='object'?w.depleted:{};for(const [k,v] of Object.entries(depleted).slice(0,300))if(/^[he](?:\d+|\-start\-[a-z]+)$/.test(k))imported.depleted[k]=clamp(num(v),0,100);imported.wildlifeLog=Array.isArray(w.wildlifeLog)?w.wildlifeLog.filter(k=>Object.hasOwn(ANIMALS,k)).slice(0,5):[];return imported}
root.addEventListener('change',async e=>{if(e.target?.id!=='hf3-import')return;const f=e.target.files?.[0];e.target.value='';if(!f)return;try{if(f.size>500000)throw Error('Backup file is too large');const data=JSON.parse(await f.text());const imported=safeImport(data);const choice=window.prompt('Restore into which world slot? Enter 1, 2, or 3.');const i=Number(choice)-1;if(!Number.isInteger(i)||i<0||i>2)return;if(worlds[i]&&!window.confirm(`Replace ${worlds[i].name} in slot ${i+1}? This cannot be undone.`))return;worlds[i]=imported;if(!writeStore(worlds))throw Error('Browser storage is blocked');home();toast('3D world backup imported.')}catch(err){window.alert('Could not import backup: '+err.message)}});
