function vertexShader(){return `
attribute vec3 aPos;attribute vec3 aNormal;attribute vec4 aColor;
uniform mat4 uVP;uniform vec3 uCamera;uniform vec3 uSun;uniform vec3 uFog;uniform vec3 uLamp;
uniform float uDay;uniform float uHasLamp;uniform float uTime;
varying vec3 vCol;varying vec3 vWorld;varying vec3 vNormal;varying float vDistance;varying float vGlow;
void main(){vec3 pos=aPos;
 if(pos.y>2.5 && aColor.g>aColor.r*1.24 && aColor.g>aColor.b*1.07)
  pos.xz+=vec2(sin(pos.z*.45+uTime*.75),cos(pos.x*.5+uTime*.68))*.065;
 vec3 n=normalize(aNormal);float direct=max(dot(n,normalize(uSun)),0.0);
 float hemi=.23+.30*max(n.y,0.0);float daylight=.18+uDay*.78;
 float light=(hemi+daylight*.26+direct*(.14+uDay*.75));
 float distLamp=distance(pos,uLamp);float lamp=(1.0-smoothstep(3.0,34.0,distLamp))*uHasLamp*.72;
 vGlow=aColor.a;vCol=aColor.rgb*(light+lamp)+aColor.rgb*aColor.a*.86;
 vWorld=pos;vNormal=n;vDistance=distance(pos,uCamera);
 gl_Position=uVP*vec4(pos,1.0);
}`}
function fragmentShader(){return `
precision mediump float;uniform vec3 uFog;uniform float uDay;uniform float uTime;
varying vec3 vCol;varying vec3 vWorld;varying vec3 vNormal;varying float vDistance;varying float vGlow;
void main(){
 float grain=(sin(vWorld.x*.57+sin(vWorld.z*.4))*sin(vWorld.z*.47))*.032;
 float horizonMist=clamp((8.0-vWorld.y)/22.0,0.0,.25);
 float fog=smoothstep(95.0,258.0,vDistance)*(.75+horizonMist);
 vec3 col=vCol*(1.0+grain);
 col=mix(col,uFog,fog);
 col=pow(clamp(col*vec3(.86,.88,.93),0.0,1.9),vec3(1.14));
 gl_FragColor=vec4(col,1.0);
}`}
function skyVertex(){return `attribute vec2 aXY;varying vec2 vUV;void main(){vUV=aXY*.5+.5;gl_Position=vec4(aXY,1.0,1.0);}`}
function skyFragment(){return `
precision mediump float;varying vec2 vUV;uniform float uDay;uniform float uClock;uniform float uTime;
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
void main(){
 vec3 nightTop=vec3(.017,.042,.093),nightHorizon=vec3(.075,.12,.19);
 vec3 dayTop=vec3(.12,.30,.42),dayHorizon=vec3(.64,.72,.65);
 float h=pow(1.0-clamp(vUV.y,0.0,1.0),1.65);
 vec3 col=mix(mix(nightTop,nightHorizon,h),mix(dayTop,dayHorizon,h),uDay);
 float sunset=1.0-smoothstep(.16,.50,abs(uClock-.64));
 col+=vec3(.30,.13,.07)*sunset*pow(h,2.5);
 vec2 sunPos=vec2(.72,.41+sin((uClock-.13)*6.2831)*.25);
 float dist=length((vUV-sunPos)*vec2(1.7,1.0));
 col+=vec3(.95,.56,.22)*pow(max(0.0,1.0-dist*2.0),6.0)*uDay*.28;
 float st=hash(floor(gl_FragCoord.xy/13.0));float star=step(.994,st)*pow(max(0.0,1.0-length(fract(gl_FragCoord.xy/13.0)-.5)*2.3),8.0);
 col+=vec3(.7,.82,.93)*star*(1.0-uDay)*.74;
 float moon=1.0-smoothstep(.012,.02,length((vUV-vec2(.19,.74))*vec2(1.3,1.0)));
 col+=vec3(.69,.80,.90)*moon*(1.0-uDay)*.40;
 gl_FragColor=vec4(col,1.0);
}`}
function shader(kind,src){const x=gl.createShader(kind);gl.shaderSource(x,src);gl.compileShader(x);if(!gl.getShaderParameter(x,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(x));return x}
function initGL(){try{
 gl=canvas.getContext('webgl',{alpha:false,antialias:true,depth:true,powerPreference:'high-performance'})||canvas.getContext('experimental-webgl');if(!gl)return;
 const link=(vert,frag)=>{const pr=gl.createProgram();gl.attachShader(pr,shader(gl.VERTEX_SHADER,vert));gl.attachShader(pr,shader(gl.FRAGMENT_SHADER,frag));gl.linkProgram(pr);if(!gl.getProgramParameter(pr,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(pr));return pr};
 program=link(vertexShader(),fragmentShader());
 gl.useProgram(program);for(const n of ['aPos','aNormal','aColor'])attributes[n]=gl.getAttribLocation(program,n);
 for(const n of ['uVP','uCamera','uSun','uFog','uLamp','uDay','uHasLamp','uTime'])uniforms[n]=gl.getUniformLocation(program,n);
 skyProgram=link(skyVertex(),skyFragment());gl.useProgram(skyProgram);skyAttrs.xy=gl.getAttribLocation(skyProgram,'aXY');
 for(const n of ['uDay','uClock','uTime'])skyUniforms[n]=gl.getUniformLocation(skyProgram,n);
 skyBuffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,skyBuffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);
 gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);gl.disable(gl.CULL_FACE);
 terrainBuffer=gl.createBuffer();staticBuffer=gl.createBuffer();dynamicBuffer=gl.createBuffer();
 canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(raf);toast('3D graphics paused. Reload to restore the renderer.',10)});
 canvas.addEventListener('webglcontextrestored',()=>location.reload());
 }catch(e){console.error('Hollow Frontier WebGL startup:',e);gl=null;}}
function bind(buffer){gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.vertexAttribPointer(attributes.aPos,3,gl.FLOAT,false,40,0);gl.vertexAttribPointer(attributes.aNormal,3,gl.FLOAT,false,40,12);gl.vertexAttribPointer(attributes.aColor,4,gl.FLOAT,false,40,24)}

const palette={ground:[.23,.43,.34],ground2:[.18,.37,.30],path:[.39,.35,.27],tree:[.09,.31,.25],pine:[.13,.37,.29],pine2:[.22,.48,.34],bark:[.29,.23,.19],stone:[.40,.48,.47],stone2:[.54,.61,.59],steel:[.26,.40,.45],steel2:[.48,.61,.60],gold:[.83,.60,.29],bright:[.40,.94,.78],light:[1,.77,.36],shadow:[.09,.17,.21],fog:[.39,.52,.60],red:[.95,.32,.28],player:[.72,.84,.82],ash:[.36,.38,.36],ice:[.76,.82,.81],moss:[.23,.48,.36],water:[.12,.34,.40]};
class Builder{constructor(){this.data=[]}tri(a,b,c,color,em=0){let n=norm(cross(sub(b,a),sub(c,a)));if(!Number.isFinite(n[0]))n=[0,1,0];for(const v of [a,b,c])this.data.push(v[0],v[1],v[2],n[0],n[1],n[2],color[0],color[1],color[2],em)}quad(a,b,c,d,col,em=0){this.tri(a,b,c,col,em);this.tri(a,c,d,col,em)}box(x,y,z,sx,sy,sz,col,em=0){const x0=x-sx/2,x1=x+sx/2,y0=y,y1=y+sy,z0=z-sz/2,z1=z+sz/2;const a=[x0,y0,z0],b=[x1,y0,z0],c=[x1,y0,z1],d=[x0,y0,z1],e=[x0,y1,z0],f=[x1,y1,z0],g=[x1,y1,z1],h=[x0,y1,z1];this.quad(e,f,g,h,col,em);this.quad(a,d,c,b,col,em);this.quad(a,b,f,e,col,em);this.quad(b,c,g,f,col,em);this.quad(c,d,h,g,col,em);this.quad(d,a,e,h,col,em)}cone(x,y,z,r,height,col,sides=7){const peak=[x,y+height,z];for(let i=0;i<sides;i++){const a=i/sides*Math.PI*2,b=(i+1)/sides*Math.PI*2;this.tri([x+r*Math.cos(a),y,z+r*Math.sin(a)],[x+r*Math.cos(b),y,z+r*Math.sin(b)],peak,col)}}cylinder(x,y,z,r,height,col,sides=7){for(let i=0;i<sides;i++){const a=i/sides*Math.PI*2,b=(i+1)/sides*Math.PI*2;const p=[x+r*Math.cos(a),y,z+r*Math.sin(a)],q=[x+r*Math.cos(b),y,z+r*Math.sin(b)];this.quad(p,q,[q[0],y+height,q[2]],[p[0],y+height,p[2]],col)}}disc(x,y,z,r,col,em=0){const N=10;for(let i=0;i<N;i++){const a=i*2*Math.PI/N,q=(i+1)*2*Math.PI/N;this.tri([x,y,z],[x+Math.cos(a)*r,y,z+Math.sin(a)*r],[x+Math.cos(q)*r,y,z+Math.sin(q)*r],col,em)}}oct(x,y,z,r,col,em=0){const a=[x+r,y,z],b=[x,y,z+r],c=[x-r,y,z],d=[x,y,z-r],t=[x,y+r*1.35,z],bt=[x,y-r*.6,z];for(const [v,w] of [[a,b],[b,c],[c,d],[d,a]]){this.tri(v,w,t,col,em);this.tri(w,v,bt,col,em)}}finish(){return new Float32Array(this.data)}}
class ChunkBuilder{
 constructor(size=86){this.size=size;this.chunks=new Map()}
 select(x,z){const ix=Math.floor((x+WORLD_RADIUS)/this.size),iz=Math.floor((z+WORLD_RADIUS)/this.size),key=ix+','+iz;
  if(!this.chunks.has(key))this.chunks.set(key,{x:ix*this.size-WORLD_RADIUS+this.size/2,z:iz*this.size-WORLD_RADIUS+this.size/2,b:new Builder()});return this.chunks.get(key).b}
 tri(a,b,c,col,em=0){const x=(a[0]+b[0]+c[0])/3,z=(a[2]+b[2]+c[2])/3;this.select(x,z).tri(a,b,c,col,em)}
 quad(a,b,c,d,col,em=0){const x=(a[0]+b[0]+c[0]+d[0])/4,z=(a[2]+b[2]+c[2]+d[2])/4;this.select(x,z).quad(a,b,c,d,col,em)}
 box(x,y,z,...rest){this.select(x,z).box(x,y,z,...rest)}
 cone(x,y,z,...rest){this.select(x,z).cone(x,y,z,...rest)}
 cylinder(x,y,z,...rest){this.select(x,z).cylinder(x,y,z,...rest)}
 oct(x,y,z,...rest){this.select(x,z).oct(x,y,z,...rest)}
 disc(x,y,z,...rest){this.select(x,z).disc(x,y,z,...rest)}
}
function uploadChunks(builder,old){for(const c of old||[])gl.deleteBuffer(c.buffer);const result=[];
 for(const part of builder.chunks.values()){const data=part.b.finish();if(!data.length)continue;const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);result.push({x:part.x,z:part.z,buffer,count:data.length/10})}return result;}
function chunkVisible(chunk,eye,forward){const dx=chunk.x-eye[0],dz=chunk.z-eye[2],d=Math.hypot(dx,dz);
 if(d>315)return false;const facing=dx*forward[0]+dz*forward[2];if(d>135&&facing< -95)return false;return true}
function meshTree(b,x,z,r=1,variant=0){const h=terrain(x,z),biome=biomeAt(x,z);
 b.disc(x+.5*r,h+.025,z+.5*r,1.8*r,[.14,.24,.20]);
 if(biome==='Lumen Marsh'&&variant%4===0){b.cylinder(x,h,z,.15*r,2.3*r,palette.stone);b.cone(x,h+1.5*r,z,1.2*r,2.6*r,[.24,.55,.55],6);b.oct(x,h+4.2*r,z,.32*r,palette.bright,.95);return}
 if(biome==='Ashwood Expanse'&&variant%3===0){b.cylinder(x,h,z,.22*r,6*r,[.23,.21,.22],6);b.cylinder(x+1.0*r,h+3*r,z+.5*r,.08*r,2.7*r,[.24,.22,.23],5);return}
 const frost=biome==='Frostline Ridge',ashen=biome==='Ashwood Expanse',broadleaf=variant%7===0&&!(frost||ashen);
 const bark=ashen?[.26,.24,.23]:palette.bark,leaf=frost?[.46,.61,.59]:ashen?[.27,.31,.29]:variant%3===0?palette.pine2:palette.tree;
 b.cylinder(x,h,z,.23*r,3.2*r,bark,6);
 if(broadleaf){b.oct(x,h+4.7*r,z,2*r,leaf);for(let t=0;t<3;t++){const ang=t*2.1;b.oct(x+Math.sin(ang)*1.25*r,h+4.0*r,z+Math.cos(ang)*1.25*r,1.35*r,leaf)}}
 else{b.cone(x,h+1.6*r,z,1.95*r,4.3*r,leaf,8);b.cone(x,h+3.25*r,z,1.65*r,4.15*r,frost?[.56,.67,.67]:variant%2?palette.pine:palette.pine2,8);b.cone(x,h+4.9*r,z,1.25*r,3.7*r,leaf,8)}
}
function nodeSeed(seed,exp=false){const rand=randSeed((seed^(exp?0x83a71:0xf921d))>>>0),out=[];const kinds=['wood','wood','wood','stone','stone','scrap','berry','berry','lumen'];
 for(let i=0;i<340;i++){
 let x=i<130?rand()*218-109:rand()*608-304,z=i<130?rand()*218-109:rand()*608-304;
 if(Math.hypot(x,z)<11){x+=22;z+=14}if(Math.hypot(x-55,z-30)<10){x-=11;z+=15}
 let type=kinds[Math.floor(rand()*kinds.length)];if(biomeAt(x,z)==='Lumen Marsh'&&rand()<.19)type='lumen';if(!exp&&type==='lumen'&&rand()<.65)continue;
 out.push({id:`${exp?'e':'h'}${i}`,type,x,z,qty:type==='wood'||type==='stone'?3:1});}
 if(!exp)out.push({id:'h-start-wood',type:'wood',x:8,z:7,qty:5},{id:'h-start-stone',type:'stone',x:-8,z:6,qty:5},{id:'h-start-scrap',type:'scrap',x:12,z:-4,qty:4},{id:'h-start-berry',type:'berry',x:-6,z:-4,qty:4});return out}
function makeWorld(){sceneKey=current.scene;sceneNodes=nodeSeed(current.seed,current.scene==='expedition');for(const n of sceneNodes)n.qty=Math.max(0,n.qty-(num(current.depleted[n.id])||0));
 const r=randSeed((current.seed^(current.scene==='expedition'?0xde0031:0x41fa2))>>>0);
 const ground=new ChunkBuilder(),M=306,step=5.1;
 for(let x=-M;x<M;x+=step)for(let z=-M;z<M;z+=step){const h1=terrain(x,z),h2=terrain(x+step,z),h3=terrain(x+step,z+step),h4=terrain(x,z+step);let col=biomeColor(x,z);const steep=Math.max(Math.abs(h1-h2),Math.abs(h2-h3),Math.abs(h3-h4),Math.abs(h4-h1));if(steep>1.4)col=col.map((v,i)=>v*.62+[.14,.13,.11][i]*.38);
 ground.quad([x,h1,z],[x,h4,z+step],[x+step,h3,z+step],[x+step,h2,z],col)}
 terrainChunks=uploadChunks(ground,terrainChunks);terrainCount=terrainChunks.reduce((a,c)=>a+c.count,0);
 const b=new ChunkBuilder();
 for(let i=0;i<760;i++){let x=r()*610-305,z=r()*610-305;if(Math.hypot(x,z)<13||Math.hypot(x-55,z-30)<10||Math.hypot(x+127,z-109)<13||Math.hypot(x-180,z-165)<17)continue;
 if(r()<.095){b.oct(x,terrain(x,z)+.55,z,.8+r()*.8,palette.stone)}else meshTree(b,x,z,.7+r()*.8,i)}
 for(let i=0;i<650;i++){let x=r()*600-300,z=r()*600-300;if(Math.hypot(x,z)<14)continue;const h=terrain(x,z),biome=biomeAt(x,z);
 b.disc(x+.5*r,h+.025,z+.5*r,1.8*r,[.14,.24,.20]);
 if(biome==='Lumen Marsh'&&r()<.3){b.oct(x,h+.30,z,.3,palette.bright,.52);continue}
 const tone=biome==='Frostline Ridge'?[.58,.70,.70]:biome==='Ashwood Expanse'?[.37,.40,.33]:[.22,.50,.33];b.cone(x,h,z,.15+r()*.12,.5+r()*.65,tone,4)}
 // Narrow irregular trail connects starting camp with Meridian relay.
 if(current.scene==='home')for(let i=0;i<66;i++){const tt=i/65,x=tt*55,z=tt*30+Math.sin(tt*5)*3,h=terrain(x,z)+.02;b.box(x,h,z,2.6,.06,2,palette.path)}
 for(const n of sceneNodes){if(n.qty<=0)continue;const h=terrain(n.x,n.z);
 if(n.type==='wood')meshTree(b,n.x,n.z,.87,8);
 if(n.type==='stone'){b.oct(n.x,h+.65,n.z,.86,palette.stone);b.oct(n.x+.5,h+.25,n.z+.45,.52,palette.stone2)}
 if(n.type==='scrap'){b.box(n.x,h,n.z,1.3,.65,1.3,palette.steel);b.box(n.x,h+.7,n.z,1.45,.13,1.45,palette.gold);b.cylinder(n.x+.65,h+.1,n.z,.12,1.1,palette.steel2)}
 if(n.type==='berry'){b.cylinder(n.x,h,n.z,.24,.8,palette.tree);for(let k=0;k<3;k++)b.oct(n.x+Math.cos(k*2.1)*.5,h+.95,n.z+Math.sin(k*2.1)*.5,.28,[.65,.43,.68],.15)}
 if(n.type==='lumen'){b.oct(n.x,h+.75,n.z,.78,palette.bright,.9);b.oct(n.x+.55,h+.31,n.z,.34,palette.steel2,.25)}}
 function facility(x,z,kind){const h=terrain(x,z);
 b.cylinder(x,h,z,8,.6,palette.stone,10);b.cylinder(x,h+.6,z,6,.35,palette.steel,10);
 if(kind==='relay'){b.box(x,h+.8,z,5,5,5,palette.steel2);b.cylinder(x,h+5,z,.65,15,palette.steel,9);b.box(x,h+18,z,1.5,1.4,1.5,current.relay?palette.bright:palette.red,current.relay?.95:.23);b.box(x,h+12,z,10,.6,.8,palette.steel2);b.box(x,h+3,z+2.8,3.2,1.4,.28,palette.shadow)}
 if(kind==='archive'){b.box(x,h+.8,z,15,3.5,10,palette.steel);b.box(x,h+4.3,z,11,3.5,7,palette.steel2);b.box(x,h+7.8,z,14,1.2,9,palette.steel);b.oct(x,h+10,z,1.5,palette.bright,1.1);
 for(let t=-1;t<=1;t++)b.box(x+t*4,h+1,z+5,2.5,2.8,.2,palette.shadow)}
 if(kind==='observatory'){b.cylinder(x,h+.8,z,5,11,palette.steel,10);b.cylinder(x,h+12,z,8,1.3,palette.steel2,12);b.oct(x,h+16,z,5,palette.steel2);b.oct(x,h+20,z,1.6,palette.bright,1.6)}
 if(kind==='core'){b.cylinder(x,h+.8,z,9,2,palette.steel,10);for(let j=0;j<8;j++){const a=j*Math.PI/4;b.cylinder(x+Math.sin(a)*5,h+2,z+Math.cos(a)*5,.4,8,palette.steel2,6)}b.oct(x,h+8,z,4.5,palette.bright,1.6)}
 }
 if(current.scene==='home'){
 facility(55,30,'relay');facility(-127,109,'archive');facility(180,165,'observatory');facility(-155,-150,'core');
 const px=15,pz=17,py=terrain(px,pz);b.cylinder(px,py,pz,3,.3,palette.steel);b.cylinder(px,py+.4,pz,2.3,.2,palette.bright,9);
 // Scenic biome-specific areas: Lumen wetlands, ridge markers, abandoned industrial quarry.
 for(let j=0;j<32;j++){const x=125+(j%8)*7,z=-160+Math.floor(j/8)*9,h=terrain(x,z);b.cylinder(x,h,z,1.4,.5,palette.water,8);if(j%5===0)b.oct(x,h+.8,z,.55,palette.bright,.8)}
 for(let j=0;j<15;j++){let x=-187+j*5,z=-145+(j%3)*7,h=terrain(x,z);b.box(x,h,z,3,1.4,2.0,palette.steel);if(j%4===0)b.cylinder(x,h+1.4,z,.3,2.5,palette.gold)}
 }else{const x=-13,z=-6,h=terrain(x,z);b.box(x,h,z,9,2,9,palette.steel);b.box(x,h+2,z,5,5,5,palette.steel2);b.oct(x,h+9,z,2.8,palette.bright,1)}
 for(const obj of current.scene==='home'?current.buildings:[]){const x=obj.x,z=obj.z,h=terrain(x,z);
 if(obj.kind==='campfire'){b.cylinder(x,h,z,1.1,.3,palette.stone2);b.cone(x,h+.2,z,.72,1,palette.gold,6)}
 if(obj.kind==='wall'){b.box(x,h,z,3.5,2,1.0,palette.bark);b.box(x,h+2,z,3.5,.3,1.1,palette.stone)}
 if(obj.kind==='generator'){b.box(x,h,z,3.5,2.2,2.4,palette.steel);b.box(x,h+2.2,z,3,.4,2.5,palette.steel2);b.box(x,h+1.1,z+1.3,1.3,.7,.13,obj.fuel>0?palette.bright:palette.gold,obj.fuel>0?.65:0);b.cylinder(x+1.5,h+2.3,z,.38,1.3,palette.stone)}
 if(obj.kind==='collector'){b.box(x,h,z,3,1.5,3,palette.steel2);b.cylinder(x,h+1.5,z,.65,2,palette.gold);b.cone(x,h+3,z,1.2,1.4,palette.steel,6)}
 if(obj.kind==='lamp'){b.cylinder(x,h,z,.21,6,palette.steel);b.oct(x,h+6.4,z,.8,palette.light,.95)}
 if(obj.kind==='beacon'){b.box(x,h,z,1.8,1.8,1.8,palette.steel2);b.oct(x,h+2.4,z,.8,palette.bright,1)}}
 staticChunks=uploadChunks(b,staticChunks);staticCount=staticChunks.reduce((a,c)=>a+c.count,0);creatures=[];spawnClock=0;collectorClock=0;populateWildlife();
}
function makeHUD(){const build=root.querySelector('#hf3-craft');const options=['campfire','generator','collector','lamp','wall','beacon','habitat'];build.innerHTML=options.map(k=>`<button class="btn" data-action="build" data-kind="${k}" title="${esc(costLabel(k))}">${esc(NAMES[k])}<small>${esc(costLabel(k))}</small></button>`).join('');updateHUD()}

function storyTarget(){if(!current)return {x:55,z:30,label:'Restore the relay'};
 if(current.scene==='expedition')return {x:-13,z:-6,label:'Investigate the Lumen station'};
 if(!current.relay)return {x:55,z:30,label:'Restore the Meridian relay · 12 scrap + 8 stone'};
 if((current.chapter||0)<3)return {x:-127,z:109,label:'Find the lost Ashwood Archive · chapter II'};
 if(current.chapter===3)return {x:180,z:165,label:'Reach Frostline Observatory · chapter III'};
 if(current.chapter===4)return {x:-155,z:-150,label:'Open the Ironfall signal vault · final chapter'};
 return {x:15,z:17,label:'The frontier is yours · discover, build and survive'};
}
function drawMiniMap(){const c=root.querySelector('#hf3-minimap');if(!c||!current)return;
 const ctx=c.getContext('2d');if(!ctx)return;
 const w=c.width,h=c.height;const X=x=>(x+WORLD_RADIUS)/(2*WORLD_RADIUS)*w,Z=z=>(z+WORLD_RADIUS)/(2*WORLD_RADIUS)*h;
 const paletteMap={'Emerald Wilds':'#376a56','Ashwood Expanse':'#65605c','Ironfall Quarry':'#867666','Lumen Marsh':'#21616a','Frostline Ridge':'#8cb4b6'};
 ctx.fillStyle='#10272c';ctx.fillRect(0,0,w,h);
 for(let gx=0;gx<w;gx+=7)for(let gy=0;gy<h;gy+=7){const wx=gx/w*2*WORLD_RADIUS-WORLD_RADIUS,wz=gy/h*2*WORLD_RADIUS-WORLD_RADIUS;ctx.fillStyle=paletteMap[biomeAt(wx,wz)];ctx.fillRect(gx,gy,7,7)}
 ctx.strokeStyle='rgba(210,235,220,.25)';ctx.lineWidth=1;ctx.strokeRect(1,1,w-2,h-2);
 const points=[[55,30,'R'],[-127,109,'A'],[180,165,'O'],[-155,-150,'V'],[15,17,'E']];
 for(const [x,z,label] of points){ctx.fillStyle='#f7d58d';ctx.beginPath();ctx.arc(X(x),Z(z),3.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#081c23';ctx.font='8px system-ui';ctx.textAlign='center';ctx.fillText(label,X(x),Z(z)+2.7)}
 ctx.fillStyle='#e9ffb1';const xx=X(current.player.x),zz=Z(current.player.z);ctx.beginPath();ctx.moveTo(xx,zz-5);ctx.lineTo(xx-4,zz+4);ctx.lineTo(xx+4,zz+4);ctx.closePath();ctx.fill();
}
function updateHUD(){if(!current)return;if(audioOn&&audioWind)audioWind.gain.setTargetAtTime(current.clock>.62?.28:.13,audio.currentTime,.7);const get=id=>root.querySelector('#'+id),p=current.player;
const set=(id,s)=>{const e=get(id);if(e)e.textContent=s};const meter=(id,val)=>{const e=get(id);if(e)e.style.width=clamp(val,0,100)+'%'};
set('hf3-date',`DAY ${String(current.day).padStart(2,'0')} · ${current.clock>.62||current.clock<.12?'NIGHT':current.clock>.48?'DUSK':'DAYLIGHT'}`);
set('hf3-zone',current.scene==='home'?'THE FRONTIER':'LUMEN EXPEDITION');set('hf3-biome',biomeAt(p.x,p.z).toUpperCase());
set('hf3-hp-text',Math.ceil(p.hp));set('hf3-hunger-text',Math.ceil(p.hunger));set('hf3-stamina-text',Math.ceil(p.stamina));meter('hf3-hp',p.hp);meter('hf3-hunger',p.hunger);meter('hf3-stamina',p.stamina);
const target=storyTarget();
set('hf3-objective',current.scene==='expedition'?'Recover the Lumen research record':target.label);
const closest=nearest(),distance=near(p,target);const bearing=Math.atan2(target.x-p.x,target.z-p.z)-camYaw;
const wrap=Math.atan2(Math.sin(bearing),Math.cos(bearing)),arrow=Math.abs(wrap)<.4?'↑':Math.abs(wrap)>2.6?'↓':wrap>0?(wrap>1.45?'→':'↗'):(wrap< -1.45?'←':'↖');
set('hf3-nearest',closest&&closest.d<6?`Nearby: ${closest.item.type} · Press E to collect`:`WAYPOINT ${arrow} · ${Math.round(distance)}m`);
drawMiniMap();
const inv=get('hf3-inventory');if(inv)inv.innerHTML=TYPES.map(t=>`<span class="inv">${t.toUpperCase()}: <b>${num(current.inv[t])}</b></span>`).join('');
const power=gridPower();set('hf3-power',power.active?`ONLINE · ${power.active} powered generator${power.active===1?'':'s'} · ${power.collectors} extractors`:`OFFLINE · Fuel a generator to enable machinery`);
root.querySelectorAll('[data-action="build"]').forEach(b=>{b.classList.toggle('sel',b.dataset.kind===buildKind);b.disabled=current.scene==='expedition';b.title=costLabel(b.dataset.kind)});
const hint=get('hf3-hint');if(hint){hint.textContent=buildKind?`BUILD ${NAMES[buildKind].toUpperCase()}: click nearby ground to place · Esc to cancel`:closest&&closest.d<4.5?`E · COLLECT ${closest.item.type.toUpperCase()}`:current.scene==='home'&&near(p,{x:15,z:17})<5?'E · ENTER EXPEDITION':current.scene==='expedition'&&near(p,{x:0,z:0})<5?'E · RETURN HOME':`WASD move · drag to look · E interact · M map · PACK crafting`;}
}
function nearest(){if(!current)return null;let best=null;for(const n of sceneNodes){if(n.qty<=0)continue;const d=near(current.player,n);if(!best||d<best.d)best={item:n,d}}return best}
function spend(cost){for(const [a,v] of Object.entries(cost))if(num(current.inv[a])<v)return false;for(const [a,v] of Object.entries(cost))current.inv[a]-=v;return true}
function gather(){const p=current.player,n=nearest();
 if(current.scene==='home'&&current.relay&&current.chapter===2&&near(p,{x:-127,z:109})<13){
  current.chapter=3;current.discoveries.push('Archive 03 · Dr. Mara Voss: The forest is not a weapon','The lost Ashwood Archive');current.inv.lumen+=2;save();scene('archive');return}
 if(current.scene==='home'&&current.chapter===3&&near(p,{x:180,z:165})<14){
  current.chapter=4;current.discoveries.push('Frostline Observatory · The second voice','Meridian relays carry memory, not just power');save();scene('observatory');return}
 if(current.scene==='home'&&current.chapter===4&&near(p,{x:-155,z:-150})<14){
  current.chapter=5;current.discoveries.push('Ironfall Vault · The Last Dawn');save();scene('core');return}
 if(current.scene==='home'&&current.chapter>=5&&near(p,{x:-155,z:-150})<14){scene(current.ending?'ending':'core');return}
 if(current.scene==='home'&&!current.relay&&near(p,{x:55,z:30})<9){if(!spend({scrap:12,stone:8})){toast('Relay repair requires 12 scrap and 8 stone.',4);return}current.relay=true;current.chapter=2;current.discoveries.push('The First Signal');updateGeometry();save();scene('relay');return}
 if(current.scene==='home'&&near(p,{x:15,z:17})<6){expedition();return}
 if(current.scene==='expedition'&&near(p,{x:0,z:0})<6){expedition();return}
 if(current.scene==='expedition'&&near(p,{x:-13,z:-6})<7){current.inv.lumen++;current.discoveries.push('Below the Trees');toast('Lumen recovered. A hidden Meridian archive responds.');scene('lumen');save();return}
 if(n&&n.d<4.5){n.item.qty--;current.depleted[n.item.id]=num(current.depleted[n.item.id])+1;current.inv[n.item.type]=(current.inv[n.item.type]||0)+((n.item.type==='wood'||n.item.type==='stone')?2:1);
  if(n.item.type==='lumen'&&!current.discoveries.includes('Lumen resonance'))current.discoveries.push('Lumen resonance');toast(`Collected ${n.item.type}.`);playCue(n.item.type==='lumen'?750:440);updateGeometry();save();return}
 toast('Move closer to a resource, signal, or landmark.');}
function updateGeometry(){makeWorld();updateHUD()}
function craftScanner(){if(current.scanner){scan();return}if(spend(COST.scanner)){current.scanner=true;toast('Signal scanner crafted · press Space to scan.');save()}else toast('Scanner needs '+costLabel('scanner'))}
function scan(){if(!current.scanner){toast('Craft the signal scanner first.');return}scanTime=3;
const list=sceneNodes.filter(n=>n.qty>0&&near(n,current.player)<25).sort((a,b)=>near(a,current.player)-near(b,current.player));
const fauna=wildlife.filter(a=>near(a,current.player)<19&&(a.type!=='owl'||current.clock>.63||current.clock<.12));
if(fauna.length){const species=[...new Set(fauna.map(a=>a.type))];const discoveries=species.filter(k=>!current.wildlifeLog.includes(k));if(discoveries.length){current.wildlifeLog.push(...discoveries);current.inv.scrap+=discoveries.length*2;save();playCue(820)}toast(`Life signs: ${species.map(k=>ANIMALS[k].name).join(', ')}${discoveries.length?' · Field notes +'+discoveries.length*2+' scrap':''}`,5)}
else toast(list.length?`Scanner: ${list.length} signals nearby · closest is ${list[0].type} (${Math.round(near(list[0],current.player))}m)`:'Scanner: no nearby resource signals.',4)}
function gridPower(){const active=current.buildings.filter(b=>b.kind==='generator'&&(b.fuel||0)>0).length;return {active,collectors:current.buildings.filter(b=>b.kind==='collector').length,lamps:current.buildings.filter(b=>b.kind==='lamp').length}}
function fuel(){if(current.scene!=='home'){toast('Return to your settlement to fuel machines.');return}const g=current.buildings.find(b=>b.kind==='generator');if(!g){toast('Build a generator first.');return}if(!spend({wood:1})){toast('Requires 1 wood.');return}g.fuel=(g.fuel||0)+95;toast('Generator fueled for 95 seconds.');updateGeometry();save()}
function eat(){if(!spend({berry:1})){toast('You need berries.');return}current.player.hunger=clamp(current.player.hunger+24,0,100);current.player.hp=clamp(current.player.hp+8,0,100);toast('Ate berries · hunger restored.');save()}
function placeFromPointer(event){const screen=root.querySelector('#hf3-screen'),r=canvas.getBoundingClientRect(),uvx=((event.clientX-r.left)/r.width)*2-1,uvy=1-((event.clientY-r.top)/r.height)*2;if(uvx< -1||uvx>1||uvy< -1||uvy>1)return;const ray=makeCamera(),tan=Math.tan(Math.PI/6);const dir=norm([ray.forward[0]+ray.right[0]*uvx*ray.aspect*tan+ray.up[0]*uvy*tan,ray.forward[1]+ray.right[1]*uvx*ray.aspect*tan+ray.up[1]*uvy*tan,ray.forward[2]+ray.right[2]*uvx*ray.aspect*tan+ray.up[2]*uvy*tan]);if(dir[1]>=-.05){toast('Aim at the ground near your character.');return}
let t=(terrain(current.player.x,current.player.z)-ray.eye[1])/dir[1];for(let i=0;i<4;i++){const x=ray.eye[0]+dir[0]*t,z=ray.eye[2]+dir[2]*t;t=(terrain(x,z)-ray.eye[1])/dir[1]}const x=ray.eye[0]+dir[0]*t,z=ray.eye[2]+dir[2]*t;buildAt(x,z)}
function buildAt(x,z){if(!buildKind)return;if(current.scene!=='home'){toast('Build in your home settlement.');return}if(!Number.isFinite(x)||!Number.isFinite(z)||Math.hypot(x,z)>WORLD_RADIUS-8){toast('Select a location inside the frontier.');return}if(Math.hypot(x-current.player.x,z-current.player.z)>14){toast('Build closer to your explorer (within 14m).');return}if(Math.hypot(x-55,z-30)<8||Math.hypot(x-15,z-17)<5){toast('Keep expedition and relay sites clear.');return}if(!spend(COST[buildKind])){toast('Need '+costLabel(buildKind));return}current.buildings.push({kind:buildKind,x:Math.round(x*10)/10,z:Math.round(z*10)/10,fuel:0});toast(`${NAMES[buildKind]} constructed.`);playCue(660);buildKind=null;updateGeometry();save()}
function expedition(){if(current.scene==='home'){if(!current.relay){toast('Repair the Meridian relay before your first Lumen expedition.');return}current.scene='expedition';current.player.x=0;current.player.z=0;current.discoveries.push('Lumen expedition');scene('expedition')}else{current.scene='home';current.player.x=15;current.player.z=20;toast('You returned to your settlement.')}buildKind=null;makeWorld();save();updateHUD()}
function damage(amount){current.player.hp=clamp(current.player.hp-amount,0,100);if(current.player.hp<=0){current.player.hp=100;current.player.hunger=70;current.player.x=current.scene==='home'?0:0;current.player.z=0;creatures=[];toast('You retreated to safety. Your world and structures were preserved.',6);save()}}
