function showChoice(){modalKind='choice';cutscene=null;const el=root.querySelector('#hf3-modal');if(el)el.innerHTML=`<div class="modal cine-modal"><div class="dialog"><div class="overline">THE LAST DAWN / CHOOSE THE FRONTIER'S FUTURE</div><h2>What should the network become?</h2><p>Dr. Voss left two viable paths. Your choice changes this world's epilogue and remains part of its history. Your home settlement survives either ending.</p><footer><button class="btn accent" data-action="ending-contain">Contain the network</button><button class="btn" data-action="ending-listen">Listen to the network</button></footer></div></div>`}
function chooseEnding(answer){if(!['contain','listen'].includes(answer)||current.ending)return;current.ending=answer;current.chapter=6;current.discoveries.push(answer==='contain'?'The Last Dawn · Containment Protocol':'The Last Dawn · The Listening Accord');save();scene('ending')}
