function parseGLB(buffer){const view=new DataView(buffer);if(view.getUint32(0,true)!==0x46546c67||view.getUint32(4,true)!==2)throw Error('Expected glTF 2.0 GLB');let offset=12,json=null,binary=null;while(offset+8<=buffer.byteLength){const len=view.getUint32(offset,true),type=view.getUint32(offset+4,true),start=offset+8;if(start+len>buffer.byteLength)throw Error('GLB corrupt');if(type===0x4e4f534a)json=JSON.parse(new TextDecoder().decode(new Uint8Array(buffer,start,len)).trim());if(type===0x004e4942)binary=buffer.slice(start,start+len);offset=start+len}if(!json||!binary)throw Error('GLB missing JSON or BIN chunk');return new RiggedScout(json,binary)}
async function startRigLoad(){if(rigState==='ready'||rigState==='fetching')return;rigState='fetching';const request=++rigLoadAttempt;const ctrl=new AbortController(),timeout=setTimeout(()=>ctrl.abort(),9500);try{const res=await fetch(RIGGED_SCOUT_URL,{signal:ctrl.signal,mode:'cors'});if(!res.ok)throw Error('Character download '+res.status);const array=await res.arrayBuffer();if(array.byteLength>12000000)throw Error('Avatar asset exceeds budget');const scout=parseGLB(array);if(request!==rigLoadAttempt)return;riggedModel=scout;rigState='ready';toast(`Animated rigged scout ready · ${scout.skin.joints.length} joints`,4)}catch(err){if(request!==rigLoadAttempt)return;rigState='offline';console.info('Hollow Frontier: optional rigged model unavailable; using animated native explorer.',err.message)}finally{clearTimeout(timeout)}}

function frame(now){if(!current||!gl)return;const rawDelta=(now-lastTick)/1000,dt=clamp(rawDelta,0,.055);lastTick=now;if(!qualityManual&&graphicsMode==='high'&&gameStarted){adaptiveTicks++;if(rawDelta>.075)slowSamples++;if(adaptiveTicks>=65){if(slowSamples>33){graphicsMode='balanced';root.querySelector('[data-action="quality"]')?.replaceChildren('ECO');toast('Performance mode enabled. Select ECO to switch back to HQ.',5)}adaptiveTicks=0;slowSamples=0}}if(!showDialog)tick(dt);render();uiClock+=dt;if(uiClock>.28){uiClock=0;updateHUD()}const toastEl=root.querySelector('#hf3-toast');if(toastEl)toastEl.hidden=now>toastUntil;raf=requestAnimationFrame(frame)}
function tick(dt){const p=current.player;let forward=0,side=0;const down=k=>keys.has(k)||mobileKeys.has(k);if(down('w')||down('arrowup')||down('up'))forward++;if(down('s')||down('arrowdown')||down('down'))forward--;if(down('a')||down('arrowleft')||down('left'))side--;if(down('d')||down('arrowright')||down('right'))side++;
const sprint=(keys.has('shift')&&p.stamina>2&&forward>0),length=Math.hypot(forward,side)||1;forward/=length;side/=length;const speed=sprint?10.5:6;let mx=(Math.sin(camYaw)*forward+Math.cos(camYaw)*side)*speed*dt,mz=(Math.cos(camYaw)*forward-Math.sin(camYaw)*side)*speed*dt;
const nx=clamp(p.x+mx,-WORLD_RADIUS,WORLD_RADIUS),nz=clamp(p.z+mz,-WORLD_RADIUS,WORLD_RADIUS);p.x=nx;p.z=nz;if(Math.hypot(mx,mz)>.001){motion+=dt;p.stamina=clamp(p.stamina-(sprint?11*dt:0)+(!sprint?8*dt:0),0,100);playerHeading=Math.atan2(mx,mz)}else p.stamina=clamp(p.stamina+10*dt,0,100);
bodyYaw+=Math.atan2(Math.sin(playerHeading-bodyYaw),Math.cos(playerHeading-bodyYaw))*Math.min(1,dt*8);tickWildlife(dt);const oldNight=current.clock>.63||current.clock<.12;current.clock+=dt/CYCLE;if(current.clock>=1){current.clock-=1;current.day++;if(current.scene==='expedition')current.expNights=(current.expNights||0)+1;toast(`Day ${current.day}. The frontier is still watching.`,5);save()}
const night=current.clock>.63||current.clock<.12;p.hunger=clamp(p.hunger-dt*.19-(sprint?dt*.1:0),0,100);if(p.hunger<1)damage(dt*.9);
if(night&&!oldNight)toast('Night is falling. The Frontier is changing.',5);
 spawnClock+=dt;
 if(night&&spawnClock>17&&creatures.length<4){spawnClock=0;const a=Math.random()*Math.PI*2,d=21+Math.random()*16,region=biomeAt(p.x,p.z);
 const roll=Math.random();const type=region==='Ironfall Quarry'?(roll<.3?'hollow':'remnant'):region==='Lumen Marsh'?(roll<.55?'mireling':'wisp'):roll<.16?'hollow':roll<.34?'wisp':'watcher';
 creatures.push({type,x:clamp(p.x+Math.cos(a)*d,-WORLD_RADIUS,WORLD_RADIUS),z:clamp(p.z+Math.sin(a)*d,-WORLD_RADIUS,WORLD_RADIUS),timer:0})}
 if(!night)creatures=creatures.filter(e=>near(p,e)<13&&e.type==='wisp');
 const hasPower=current.scene==='home'&&gridPower().active>0;
 for(const e of creatures){let dx=p.x-e.x,dz=p.z-e.z,d=Math.hypot(dx,dz)||1,repel=false;
 if(e.type==='wisp'){e.x+=Math.sin(performance.now()*.0015+e.z)*dt*1.6;e.z+=Math.cos(performance.now()*.001+e.x)*dt*1.2;continue}
 for(const light of current.scene==='home'?current.buildings:[]){if(light.kind==='campfire'||(light.kind==='lamp'&&hasPower)){if(Math.hypot(light.x-e.x,light.z-e.z)<15){repel=true;dx=e.x-light.x;dz=e.z-light.z;d=Math.hypot(dx,dz)||1;break}}}
 const speedE=repel?3.5:e.type==='remnant'?1.05:e.type==='hollow'?.75:e.type==='mireling'?2.5:1.65*(hasPower?1.11:1);
 e.x=clamp(e.x+dx/d*dt*speedE,-WORLD_RADIUS,WORLD_RADIUS);e.z=clamp(e.z+dz/d*dt*speedE,-WORLD_RADIUS,WORLD_RADIUS);
 if(near(p,e)<2.0){e.timer+=dt;if(e.timer>1.45){damage(e.type==='remnant'?6:e.type==='hollow'?7:4);e.timer=0;toast(`${MOB_NAMES[e.type]||'A creature'} is close. Seek shelter or follow the lights!`)}}}
 if(current.scene==='home'){let powered=false;for(const b of current.buildings)if(b.kind==='generator'&&b.fuel>0){b.fuel=Math.max(0,b.fuel-dt);powered=true}if(powered){collectorClock+=dt;if(collectorClock>19){collectorClock=0;const cnt=current.buildings.filter(b=>b.kind==='collector').length;if(cnt){current.inv.stone+=cnt;current.inv.scrap+=cnt;toast(`Extractor network delivered ${cnt} stone and ${cnt} scrap.`);save()}}}}
scanTime=Math.max(0,scanTime-dt);autosave+=dt;if(autosave>20){autosave=0;save()}}
